package com.crz.blue;

import android.Manifest;
import android.app.*;
import android.os.*;
import android.content.*;
import android.content.pm.*;
import android.graphics.*;
import android.location.*;
import android.media.AudioManager;
import android.provider.Settings;
import android.view.*;
import java.text.*;
import java.util.*;

public class MainActivity extends Activity {
  LocationManager location; double speed=0, trip=0; Location last; long started; boolean night=true; boolean gpsActive=false; long lastFix=0;
  final String[] labels={"HOME","NAV","MUSIC","VIDEO","PHONE","RADIO","BROWSER","SETTINGS","APPS"};
  Dashboard dashboard;
  @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512); started=System.currentTimeMillis(); trip=getPreferences(0).getFloat("trip",0); night=getPreferences(0).getBoolean("night",true); dashboard=new Dashboard();setContentView(dashboard);location=(LocationManager)getSystemService(LOCATION_SERVICE);if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION},4);else startGps();}
  void startGps(){if(gpsActive)return;try{gpsActive=true;location.requestLocationUpdates(LocationManager.GPS_PROVIDER,1000,1,l->{lastFix=System.currentTimeMillis();speed=l.hasSpeed()?Math.max(0,l.getSpeed()*3.6):0;if(last!=null&&l.hasAccuracy()&&l.getAccuracy()<25&&last.hasAccuracy()&&last.getAccuracy()<25&&l.getTime()>last.getTime()&&last.distanceTo(l)<100&&last.distanceTo(l)>3){trip+=last.distanceTo(l)/1000.0;getPreferences(0).edit().putFloat("trip",(float)trip).apply();}last=l;dashboard.invalidate();});}catch(Exception ignored){}}
  @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==4&&g.length>0&&g[0]==0)startGps();}
  @Override protected void onPause(){super.onPause();speed=0;dashboard.invalidate();}
  void launch(String type){try{
   String assigned=getPreferences(0).getString("app_"+type,"");
   if(!assigned.isEmpty()){Intent configured=getPackageManager().getLaunchIntentForPackage(assigned);if(configured!=null){startActivity(configured);return;}}
   Intent i=null;switch(type){case "NAV":i=new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("geo:0,0?q="));break;case "MUSIC":chooseApp("music", "MUSIC");return;case "VIDEO":i=new Intent(Intent.ACTION_VIEW);i.setType("video/*");break;case "PHONE":chooseApp("bluetooth", "PHONE");return;case "RADIO":chooseApp("radio", "RADIO");return;case "BROWSER":i=new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://www.google.com"));break;case "SETTINGS":i=new Intent("android.settings.SETTINGS");break;case "APPS":chooseApp("", "");return;default:return;}startActivity(i);}catch(Exception e){chooseApp("", "");}}
  void chooseApp(String filter,String shortcut){PackageManager pm=getPackageManager();Intent intent=new Intent(Intent.ACTION_MAIN);intent.addCategory(Intent.CATEGORY_LAUNCHER);java.util.List<ResolveInfo> apps=pm.queryIntentActivities(intent,0);ArrayList<ResolveInfo> shown=new ArrayList<>();for(ResolveInfo a:apps){String name=a.loadLabel(pm).toString().toLowerCase(Locale.ROOT);if(filter.isEmpty()||name.contains(filter)||(filter.equals("radio")&&name.contains("fm")))shown.add(a);}if(shown.isEmpty()&&!filter.isEmpty()){new AlertDialog.Builder(this).setTitle("App not found").setMessage("Choose the original head-unit app from the complete app list.").setPositiveButton("Choose app",(d,w)->chooseApp("", shortcut)).setNegativeButton("Cancel",null).show();return;}String[] names=new String[shown.size()];for(int j=0;j<shown.size();j++)names[j]=shown.get(j).loadLabel(pm).toString();new AlertDialog.Builder(this).setTitle(filter.isEmpty()?"Installed apps":"Choose " + shortcut.toLowerCase(Locale.ROOT) + " app").setItems(names,(d,n)->{ResolveInfo a=shown.get(n);Intent i=pm.getLaunchIntentForPackage(a.activityInfo.packageName);if(i!=null){if(!shortcut.isEmpty())getPreferences(0).edit().putString("app_"+shortcut,a.activityInfo.packageName).apply();startActivity(i);}}).show();}
  void resetTrip(){new AlertDialog.Builder(this).setTitle("Reset trip?").setMessage("Clear the saved GPS trip distance?").setPositiveButton("Reset",(d,w)->{trip=0;last=null;getPreferences(0).edit().putFloat("trip",0).apply();dashboard.invalidate();}).setNegativeButton("Cancel",null).show();}
  void media(int key){AudioManager a=(AudioManager)getSystemService(AUDIO_SERVICE);a.dispatchMediaKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,key));a.dispatchMediaKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,key));}
  class Dashboard extends View {Paint p=new Paint(3);Bitmap bg;Canvas c;float sx,sy;Dashboard(){super(MainActivity.this);try{bg=BitmapFactory.decodeStream(getAssets().open("car_background.png"));}catch(Exception ignored){}}void color(int col){p.setColor(col);p.setStyle(Paint.Style.FILL);p.setStrokeWidth(2);}int blue=Color.rgb(0,137,255),white=Color.WHITE,grey=Color.rgb(185,196,210);
   void txt(String s,float x,float y,int size,int col,boolean bold){color(col);p.setTypeface(bold?Typeface.create("sans-serif",Typeface.BOLD):Typeface.create("sans-serif",0));p.setTextSize(size);c.drawText(s,x,y,p);}void line(float x,float y,float xx,float yy,int col){color(col);p.setStrokeWidth(2);c.drawLine(x,y,xx,yy,p);}void panel(float x,float y,float w,float h){color(0xD9000814);c.drawRoundRect(x,y,x+w,y+h,17,17,p);color(blue);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.5f);c.drawRoundRect(x,y,x+w,y+h,17,17,p);p.setStyle(Paint.Style.FILL);}
   @Override protected void onDraw(Canvas canvas){c=canvas;sx=getWidth()/1600f;sy=getHeight()/900f;c.save();c.scale(sx,sy);c.drawColor(Color.BLACK);if(bg!=null){color(white);c.drawBitmap(bg,null,new Rect(130,125,1600,720),p);}color(0xB8000000);c.drawRect(0,0,155,900,p);line(150,0,150,900,0xFF263441);
    String[] icons={"⌂","➤","♫","▶","☎","▣","◎","⚙","▦"};for(int i=0;i<9;i++){int y=90+i*86;if(i==0)panel(17,50,112,77);txt(icons[i],58,y,39,i==0?blue:white,true);}String greet=new SimpleDateFormat("HH",Locale.getDefault()).format(new Date());int hr=Integer.parseInt(greet);txt(hr<12?"Good morning":hr<17?"Good afternoon":"Good night",190,60,35,white,true);txt(new SimpleDateFormat("EEEE, d MMMM",Locale.getDefault()).format(new Date()),190,100,22,grey,false);txt(new SimpleDateFormat("h:mm a",Locale.getDefault()).format(new Date()),850,67,46,white,true);txt(night?"☾  NIGHT":"☀  DAY",1390,60,25,blue,true);
    txt("Trip",720,157,18,grey,false);txt(String.format(Locale.US,"%.1f km",trip),720,188,27,white,true);txt("Drive",970,157,18,grey,false);txt(((System.currentTimeMillis()-started)/60000)+" min",970,188,27,white,true);txt("Heading",1230,157,18,grey,false);txt(last==null?"--":String.format(Locale.US,"%.0f°",last.getBearing()),1230,188,27,white,true);
    txt(String.format(Locale.US,"%.0f",System.currentTimeMillis()-lastFix>5000?0:speed),210,350,125,white,true);txt("km/h",348,350,34,grey,false);line(210,378,480,378,blue);txt(last==null||System.currentTimeMillis()-lastFix>10000?"GPS waiting for fix":"GPS speed",210,412,19,grey,false);txt("Tap trip to reset",720,216,16,grey,false);txt("HONDA  CR-Z",1240,258,35,white,true);txt("MUGEN  •  BLUE EDITION",1240,296,20,blue,true);
    panel(183,716,1370,146);txt("NOW PLAYING",442,757,18,grey,false);txt("Android media",442,798,32,white,true);txt("Use Music to select your player",442,830,19,grey,false);txt("|◀",760,806,45,white,true);txt("▶❚",865,806,45,blue,true);txt("▶|",970,806,45,white,true);txt("−",1200,806,45,white,true);txt("+",1430,806,45,white,true);
    if(night){color(0x33000B22);c.drawRect(151,0,1600,125,p);}c.restore();postInvalidateDelayed(1000);}
   @Override public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()!=MotionEvent.ACTION_UP)return true;float x=e.getX()/sx,y=e.getY()/sy;if(x<155){int idx=Math.round((y-90)/86f);if(idx>=0&&idx<labels.length)launch(labels[idx]);}else if(y<105&&x>1330){night=!night;getPreferences(0).edit().putBoolean("night",night).apply();invalidate();}else if(y>130&&y<230&&x>670&&x<900){resetTrip();}else if(y>716){if(x>740&&x<850)media(KeyEvent.KEYCODE_MEDIA_PREVIOUS);else if(x<970&&x>850)media(KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE);else if(x<1090&&x>970)media(KeyEvent.KEYCODE_MEDIA_NEXT);else if(x>1150&&x<1330)((AudioManager)getSystemService(AUDIO_SERVICE)).adjustVolume(AudioManager.ADJUST_LOWER,0);else if(x>1330)((AudioManager)getSystemService(AUDIO_SERVICE)).adjustVolume(AudioManager.ADJUST_RAISE,0);else launch("MUSIC");}return true;}
  }
}
